const qs = [
  '"workspace status"',
  '"workspace_status"',
  '"workspace status" "AgentPane"',
  '"fork sizer"'
];
const rs = await Promise.all(qs.map(q => tools.exec_command({
  cmd: `entire search --json --compact ${JSON.stringify(q)}`,
  workdir: "/Users/kenneth/Projects/JusPrin",
  yield_time_ms: 30000,
  max_output_tokens: 12000
})));
rs.forEach((r,i)=>{ text(`QUERY ${qs[i]}\n${r.output}\nEXIT ${r.exit_code}`); });

const cmds = [
  ["status terms", "rg -n -i --hidden --glob '!build/**' --glob '!deps/**' --glob '!.git/**' 'workspace status|workspace_status|StatusRow|AgentPane|workspace column|resize handle' ."],
  ["mainframe files", "rg -n --hidden --glob '!build/**' --glob '!deps/**' --glob '!.git/**' 'class MainFrame|MainFrame::|m_agent|AgentPane' src/slic3r/GUI/JusPrin src/slic3r/GUI 2>/dev/null"],
  ["recent commits", "git log --all --date=iso-strict --pretty=format:'%H%x09%an%x09%ae%x09%ad%x09%s' -n 120 -- src/slic3r/GUI/JusPrin"]
];
const rs = await Promise.all(cmds.map(([label,cmd]) => tools.exec_command({
  cmd, workdir:"/Users/kenneth/Projects/JusPrin", yield_time_ms:30000, max_output_tokens:30000
})));
rs.forEach((r,i)=>text(`### ${cmds[i][0]}\n${r.output}`));

