    m_agent_toggle->SetToolTip(collapsed ? _L("Show the Agent panel") : _L("Hide the Agent panel"));
}

void StatusRow::toggle_agent_pane()
{
    if (m_agent_pane_toggle)
        m_agent_pane_toggle();
}

