        const auto& p = m_theme.palette(m_dark);
        dc.SetBackground(wxBrush(p.surface_canvas)); dc.Clear();
        dc.SetPen(wxPen(p.border_subtle));
        dc.DrawLine(0, GetClientSize().y-1, GetClientSize().x, GetClientSize().y-1);
    });

