        else if (item.action == PrintAction::Export) icon = HeaderIcon::Export;
        else if (item.action == PrintAction::Prepare) icon = HeaderIcon::Back;
        else if (item.action == PrintAction::Cancel) icon = HeaderIcon::Cancel;
