// What the estimate on a plate is worth right now. The number itself is kept
// across all three: a slice in flight or invalidated does not make the last
// honest figure worthless, and blanking it kills the comparison the reader is
// usually making. Only "never sliced" has no estimate at all.
enum class EstimateStatus : std::uint8_t {
    Current,     // this plate holds the slice the estimate came from
    Recomputing, // a slice is running; the estimate is the one it will replace
    Stale        // something invalidated the slice; the estimate predates it
};

struct WorkspacePlate
{
    PlateId                      id;
    std::string                  name;
    bool                         active{false};
    // True when this plate holds a currently valid slice result. Derived from
    // the authoritative plate state on every snapshot, never cached.
    bool                         sliced{false};
    std::vector<WorkspaceObject> objects;
    std::uint64_t                slice_result_id{0}; // zero while invalid or slicing
    // The plate's estimate: current, being recomputed, or stale. Absent only
    // when this plate has never been sliced in this session.
    std::optional<SliceEstimate> estimate;
    EstimateStatus               estimate_status{EstimateStatus::Current};
    // Which of the user's actions invalidated the slice, when that is known.
    // Empty when it is not: the card would rather say nothing than guess.
    std::string                  invalidated_by;
};

        result.can_redo          = !m_redo.empty();
        result.setup.process_preset = m_settings_available ? m_process_preset : "";
        result.setup.process_preset_dirty = m_settings.values != m_settings.preset_values;
        result.currency = m_currency;
        if (m_settings_available)
            for (const auto& [key, value] : m_settings.values) {
                const auto preset = m_settings.preset_values.find(key);
                if (preset == m_settings.preset_values.end() || preset->second == value) continue;
                const auto definition = std::find_if(m_settings.definitions.begin(), m_settings.definitions.end(),
                                                     [&](const auto& candidate) { return candidate.key == key; });
                result.preset_deltas.push_back(
                    {key, definition == m_settings.definitions.end() ? key : definition->label, preset->second, value});
            }
        for (auto& plate : result.plates)
            if (!plate.sliced) {
                plate.slice_result_id = 0;
                // A fixture may describe an estimate the plate can no longer
                // defend -- recomputing or stale -- but never a current one.
                if (plate.estimate_status == EstimateStatus::Current) plate.estimate.reset();
                continue;
            } else {
                plate.estimate_status = EstimateStatus::Current;
                plate.invalidated_by.clear();
            }
    }

    // Publishing here is part of the contract, not a fixture convenience: a
    // slice changes what consumers may say about the plate, so it has to
