    DuplicateObject,
    ImportModel,
    InspectSelection,
    WorkspaceInspect,
    ReportSliceReview,
    SettingsSearch,
    SettingsGet,
    SettingsPreviewPatch,
    SettingsApplyPatch,
    RecordBuild,
    RecordExportCopy,
    RecordPhysicalPrint
};

