    case PrintAction::Cancel: return primary ? _L("Slicing…") : _L("Cancel");
    case PrintAction::Print: return primary ? (state.plate_count > 1 ? wxString::Format(_L("Print plate %d"), state.plate_number) : _L("Print")) : _L("Print…");
